// --- PHẦN 3: Middleware bao ve Streamable HTTP MCP Endpoint (Chuan 2025-11-25) ---
import type { IncomingMessage, ServerResponse } from 'node:http';

const ALLOWED_ORIGINS = new Set([
  'https://domation.net',
  'http://127.0.0.1:3000',
]);
const EXPECTED_AUDIENCE = 'https://mcp.domation.net/erp';

export function hardenStreamableHttpMcp(
  req: IncomingMessage,
  res: ServerResponse
): boolean {
  // 1. Bat buoc kiem tra Origin header chong DNS Rebinding -> tra 403 Forbidden
  const origin = req.headers.origin;
  if (origin && !ALLOWED_ORIGINS.has(origin)) {
    res.writeHead(403, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'forbidden_origin_dns_rebinding_guard' }));
    return false;
  }

  // 2. Xac thuc Bearer Token & RFC 8707 Resource Indicator (cam token passthrough)
  const authHeader = req.headers.authorization || '';
  if (!authHeader.startsWith('Bearer ')) {
    // Tra ve 401 kem RFC 9728 Protected Resource Metadata
    res.writeHead(401, {
      'WWW-Authenticate': `Bearer resource_metadata="${EXPECTED_AUDIENCE}/.well-known/oauth-protected-resource"`,
      'Content-Type': 'application/json',
    });
    res.end(JSON.stringify({ error: 'unauthorized_missing_oauth21_token' }));
    return false;
  }

  const tokenAudience = verifyJwtAndExtractAud(authHeader.slice(7));
  if (tokenAudience !== EXPECTED_AUDIENCE) {
    res.writeHead(403, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'invalid_rfc8707_audience_binding' }));
    return false;
  }

  return true;
}

function verifyJwtAndExtractAud(_token: string): string {
  // Trien khai xac minh chu ky JWKS theo RFC 8414 / OIDC Discovery
  return EXPECTED_AUDIENCE;
}
